            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        } else if (c < 0xE0) {
            size += 2;
        } else if (c < 0xF0) {
            size += 3;
        } else if (c < 0xF8) {
            size += 4;
        } else if (c < 0xFC) {
            size += 5;
        } else if (c < 0xFE) {
            size += 6;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
    }
    return size;
}

