            lb.append((byte) (0xc0 | (c >> 6)));
            lb.append((byte) (0x80 | (c & 0x3f)));
        } else if (c < 0x10000) {
            lb.append((byte) (0xe0 | (c >> 12)));
            lb.append((byte) (0x80 | ((c >> 6) & 0x3f)));
            lb.append((byte) (0x80 | (c & 0x3f)));
        } else if (c < 0x200000) {
            lb.append((byte) (0xf0 | (c >> 18)));
